import 'package:characters/characters.dart';

void analyzeString(String input) {
  print('--- 문자열 분석 시작 ---\n');
  print('원본 문자열: "$input"');

  // 1. Dart 기본 String 길이 (Code Units 기준)
  final dartLength = input.length;
  print('Dart String.length (코드 유닛): $dartLength');

  // 2. Characters 길이 (Grapheme Clusters 기준)
  final graphemeLength = input.characters.length;
  print('Characters.length (시각적 문자): $graphemeLength');

  // 예시: 'Hi 🇩🇰' (🇩🇰는 4개의 코드 유닛)
  // Dart Length: 7 (H, i, ' ', 4 units for 🇩🇰)
  // Grapheme Length: 4 (H, i, ' ', 🇩🇰)

  if (dartLength != graphemeLength) {
    print('\n[중요] 길이가 다릅니다. 이는 복합 문자가 포함되었음을 의미합니다.');
  }
  print('\n--- 분석 종료 ---');
}

void main() {
  analyzeString('Hello World'); // 일반 문자열 (길이 동일)
  analyzeString('Hi 🇩🇰'); // 국기 이모지 포함 (길이 다름)
  analyzeString('👨‍👩‍👧‍👦'); // 가족 이모지 (Zero Width Joiner 포함)
}

import 'package:characters/characters.dart';

class GraphemeManipulator {
  final String originalString;

  GraphemeManipulator(this.originalString);

  // 1. 마지막 그래핌 클러스터 가져오기
  String getLastCharacter() {
    // String.substring(length - 1)은 복합 문자를 깨뜨릴 수 있습니다.
    return originalString.characters.last;
  }

  // 2. 마지막 N개의 그래핌 클러스터 건너뛰기 (자르기)
  String skipLastCharacters(int count) {
    // skipLast()는 시각적 문자 단위로 정확하게 자릅니다.
    return originalString.characters.skipLast(count).toString();
  }

  // 3. 그래핌 클러스터 단위로 대체
  String replaceGrapheme(String target, String replacement) {
    // 대체할 문자열도 .characters로 변환해야 안전합니다.
    return originalString.characters
        .replaceAll(target.characters, replacement.characters)
        .toString();
  }
}

void main() {
  final manipulator = GraphemeManipulator('Hello 🇰🇷');

  // 테스트 1: 마지막 문자 접근
  print('마지막 문자: ${manipulator.getLastCharacter()}'); // 🇰🇷 (깨지지 않음)

  // 테스트 2: 마지막 1개 건너뛰기
  print('마지막 1개 제거: "${manipulator.skipLastCharacters(1)}"'); // "Hello "

  // 테스트 3: 대체
  final replaced = manipulator.replaceGrapheme('🇰🇷', '🇺🇸');
  print('국기 대체 결과: "$replaced"'); // "Hello 🇺🇸"
}

import 'package:characters/characters.dart';

/// 시각적 문자(Grapheme Cluster) 단위로 안전하게 문자열을 자르는 함수
String safeTruncate(String text, int maxLength) {
  if (text.characters.length <= maxLength) {
    return text;
  }

  // take(maxLength)를 사용하여 정확히 maxLength개의 그래핌만 가져옵니다.
  final truncated = text.characters.take(maxLength).toString();

  // 잘린 문자열 뒤에 '...' 추가
  return '$truncated...';
}

