void main() {
  const complexText = 'Flutter 💙❤️💛💚💜';
  // 기본 String.substring(0, 10)은 'Flutter 💙' 까지만 자르려다 💙가 깨질 수 있음.

  print('원본: $complexText');
  print('안전하게 10자 자르기: ${safeTruncate(complexText, 10)}');
  // 결과: 'Flutter 💙❤️...' (정확히 10개의 시각적 문자 + ...)
}
